# a line of the notes of a version: "<asset>: <path> <sha256>" (the dependencies have "<name@version> – " before)
NOTES_LINE = re.compile(r"^(?P<asset>[^:]+?): (?P<path>.+) (?P<sha256>[0-9a-f]{64})$")
MAX_NOTES = 10000


# a copy of releases.bottle_coverage as of this migration: the bottle tags, newest macOS first
MACOS = ("golden_gate", "tahoe", "sequoia", "sonoma", "ventura", "monterey", "big_sur", "catalina", "mojave",
         "high_sierra", "sierra", "el_capitan")


def _bottle_coverage(tags):
    coverage = {tag: [tag] for tag in tags}
    for prefix in ("arm64_", ""):
        current = None
        for release in reversed(MACOS):
            if prefix + release in coverage:
                current = prefix + release
            elif current:
                coverage[current].append(prefix + release)
    return coverage


def _bottle_tag(asset):
    return asset.removesuffix(".bottle.tar.gz").rsplit(".", 1)[-1] if asset.endswith(".bottle.tar.gz") else ""


def _match(kind, asset, coverage):
    """What the asset pattern was matched against, as far as the asset name tells"""
    if kind == "GITHUB_RELEASE":
        return [asset]
    if kind == "HOMEBREW_FORMULA" and _bottle_tag(asset):
        # the bottles recorded with the version are the ones the formula had (or the pattern took)
        return coverage.get(_bottle_tag(asset), [_bottle_tag(asset)])
    if kind == "VSCODE_EXTENSION" and "@" in asset:
        return [asset.rsplit("@", 1)[-1].removesuffix(".vsix")]
    return []


def set_release_files(apps, schema_editor):
    # The files of the rules recorded so far, from the notes of their version. A Binary rule is one file; a rule of
    # another type can stand for several files, only known when the version has a single binary. Without notes
    # (cut off at their limit) the files stay unknown and the clean up leaves the rules.
    ReleaseVersion = apps.get_model("santa", "ReleaseVersion")
    Rule = apps.get_model("santa", "Rule")
    for version in ReleaseVersion.objects.select_related("source").exclude(notes="").iterator():
        if len(version.notes) >= MAX_NOTES:
            continue
        found_lines = [found for line in version.notes.splitlines()
                       if " – " not in line.split(": ", 1)[0] and (found := NOTES_LINE.match(line))]
        if not found_lines:
            continue
        coverage = _bottle_coverage({_bottle_tag(found["asset"]) for found in found_lines} - {""})
        files = [{"asset": found["asset"], "match": _match(version.source.kind, found["asset"], coverage),
                  "path": found["path"], "sha256": found["sha256"]} for found in found_lines]
        single = len({file["sha256"] for file in files}) == 1
        rules = []
        for rule in Rule.objects.filter(release_version=version, release_dependency=""):
            if rule.rule_type == "BINARY":
                rule.release_files = [file for file in files if file["sha256"] == rule.identifier]
            elif single:
                rule.release_files = files
            if rule.release_files:
                rules.append(rule)
        Rule.objects.bulk_update(rules, ["release_files"], batch_size=500)


